export function BrandIcon({ name, size = 28, color, title, mono = false }) {
  const ic = I[name];
  if (!ic) return null;
  const fill = mono ? 'currentColor' : (color || ic.color);
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" role="img"
         aria-label={title || ic.title} fill={fill} xmlns="http://www.w3.org/2000/svg">
      <title>{title || ic.title}</title>
      <path d={ic.d} />
    </svg>
  );
}
export const BRAND_COLOR = Object.fromEntries(Object.entries(I).map(([k,v])=>[k,v.color]));
